package au.monster.tracker;
import java.util.*;
public final class RefundTests {
    private static int passed;
    private static void eq(Object a,Object b){if(!Objects.equals(a,b))throw new AssertionError(a+" != "+b);}
    private static void test(String name,Runnable check){check.run();passed++;System.out.println("PASS "+name);}
    private static void reject(Runnable action){try{action.run();throw new AssertionError("Invalid refund accepted");}catch(IllegalArgumentException expected){}}
    private static Refunds.Observation observation(Refunds.Request r,String state,long now){return new Refunds.Observation(Ledger.id(),r.id(),r.stripe()?"re_provider":"manual-"+r.id(),state,r.recordedAt(),now,0L,"");}
    public static void main(String[] args){long now=System.currentTimeMillis();var events=new ArrayList<>(Ledger.opening(now));var sale=Ledger.event("deal",2,"card",600,25,0,"",now,null);events.add(sale);var request=new Refunds.Request(Ledger.id(),sale.id(),600,now,"Returned purchase",false);var success=observation(request,"succeeded",now);
        test("refund reduces card revenue and retains original fee",()->{Refunds.validate(Ledger.list(request),Ledger.list(success),Ledger.list(),events);var state=Refunds.state(Ledger.list(request),Ledger.list(success),events);eq(state.card(),600L);eq(state.fees(),0L);var rows=Refunds.financialRows(Ledger.list(request),Ledger.list(success),events,Map.of(),Map.of());eq(rows.get(0).revenue(),-600L);eq(rows.get(0).fees(),0L);});
        test("pending failed canceled refunds do not reduce revenue",()->{for(String state:Ledger.list("pending","failed","canceled"))eq(Refunds.state(Ledger.list(request),Ledger.list(observation(request,state,now)),events).amount(),0L);});
        test("late failed refund appends financial reversal",()->{var failed=observation(request,"failed",now+1);var rows=Refunds.financialRows(Ledger.list(request),Ledger.list(success,failed),events,Map.of(),Map.of());eq(rows.size(),2);eq(rows.get(0).revenue()+rows.get(1).revenue(),0L);});
        test("partial GST refunds and later failures remain cents-exact",()->{var a=new Refunds.Request(Ledger.id(),sale.id(),300,now,"",false);var b=new Refunds.Request(Ledger.id(),sale.id(),300,now,"",false);var rows=Refunds.financialRows(Ledger.list(a,b),Ledger.list(observation(a,"succeeded",now),observation(b,"succeeded",now+1),observation(a,"failed",now+2)),events,Map.of(sale.id(),new Finance.Tax(true,0,0,55)),Map.of());long gst=0;for(var r:rows)gst+=r.outputGst();eq(gst,-27L);});
        test("refund does not add stock before physical receipt",()->eq(Ledger.totals(events).stock(),18L));
        test("returned goods restore original FIFO cost without a purchase",()->{var returned=Ledger.event("restock",2,"none",0,0,0,"Physically returned",now+1,null);var es=new ArrayList<>(events);es.add(returned);var data=Finance.calculate(es,Map.of(),Ledger.list(),Ledger.list(),Ledger.list(),Map.of(),Map.of(returned.id(),sale.id()));eq(data.inventoryValue(),4167L);eq(data.rows().get(3).cogs(),-416L);eq(data.rows().get(3).purchases(),0L);});
        test("overrefund duplicates and stale observations rejected",()->{reject(()->Refunds.validate(Ledger.list(request,request),Ledger.list(success),Ledger.list(),events));var extra=new Refunds.Request(Ledger.id(),sale.id(),1,now,"",false);reject(()->Refunds.validate(Ledger.list(request,extra),Ledger.list(success),Ledger.list(),events));reject(()->Refunds.validate(Ledger.list(request),Ledger.list(success,observation(request,"failed",now-1)),Ledger.list(),events));});
        test("corrupted fee integer and source associations rejected",()->{reject(()->new Refunds.Observation(Ledger.id(),request.id(),"manual-"+request.id(),"succeeded",now,now,Long.MIN_VALUE,""));var wrong=new Refunds.Request(Ledger.id(),Ledger.id(),600,now,"",false);reject(()->Refunds.validate(Ledger.list(wrong),Ledger.list(),Ledger.list(),events));});
        test("unknown manual refund dates stay unknown in reports",()->{var unknown=new Refunds.Observation(Ledger.id(),request.id(),"manual-"+request.id(),"succeeded",null,now,0L,"");Refunds.validate(Ledger.list(request),Ledger.list(unknown),Ledger.list(),events);var rows=Refunds.financialRows(Ledger.list(request),Ledger.list(unknown),events,Map.of(),Map.of());eq(rows.get(0).date(),null);});
        System.out.println("REFUND RESULTS: "+passed+" passed, 0 failed.");
    }
}
